export const GENESIS_TEMPLATE_NAMES = Object.freeze(GENESIS_TEMPLATES.map((template) => template.name));

export function genesisTemplateByName(name) {
  return GENESIS_TEMPLATES.find((template) => template.name === name) ?? null;
}
